import {
  siClaude, siExpress, siFigma, siGithub, siLaravel, siLivekit, siNextdotjs, siNodedotjs,
  siPhp, siReact, siSupabase, siTailwindcss, siTypescript, siVercel, siVite,
} from './techIconPaths'

// Brand logos (Simple Icons, CC0), drawn in the pill's own text colour so they
// sit in the livery palette instead of fighting it. Paths only, generated by
// scripts/gen-tech-icons.mjs.
const BRAND = {
  'React.js': siReact,
  'Next.js': siNextdotjs,
  'Tailwind CSS': siTailwindcss,
  Supabase: siSupabase,
  Vite: siVite,
  TypeScript: siTypescript,
  'React Native': siReact,
  'Node.js': siNodedotjs,
  Express: siExpress,
  PHP: siPhp,
  Laravel: siLaravel,
  'LiveKit (WebRTC)': siLivekit,
  'Claude API': siClaude,
  Figma: siFigma,
  'Git / GitHub': siGithub,
  Vercel: siVercel,
}

// Skills that aren't brands get a plain line icon.
const GENERIC = {
  SQL: (
    <g fill="none" stroke="currentColor" strokeWidth="2">
      <ellipse cx="12" cy="5.5" rx="8" ry="3" />
      <path d="M4 5.5v13c0 1.7 3.6 3 8 3s8-1.3 8-3v-13M4 12c0 1.7 3.6 3 8 3s8-1.3 8-3" />
    </g>
  ),
  'Custom Domains': (
    <g fill="none" stroke="currentColor" strokeWidth="2">
      <circle cx="12" cy="12" r="9.5" />
      <path d="M2.5 12h19M12 2.5c2.8 2.6 4 6 4 9.5s-1.2 6.9-4 9.5c-2.8-2.6-4-6-4-9.5s1.2-6.9 4-9.5z" />
    </g>
  ),
  'SEO Optimization': (
    <g fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round">
      <circle cx="10" cy="10" r="7" />
      <path d="M15.2 15.2 21.5 21.5" />
    </g>
  ),
}

export default function TechIcon({ name }) {
  const brand = BRAND[name]
  const generic = GENERIC[name]
  if (!brand && !generic) return null
  return (
    <svg className="tech-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false">
      {brand ? <path d={brand} fill="currentColor" /> : generic}
    </svg>
  )
}
